{
  "name": "hia-theme",
  "description": "{{meta:name}} — HIA Theme Builder 生成的 Ghost 主题",
  "version": "1.0.0",
  "license": "MIT",
  "author": {
    "email": "theme@hia.example"
  },
  "config": {
    "posts_per_page": 10,
    "card_assets": true
  }
}

{{!< default}}
<section class="hia-post-list">
    {{#foreach posts}}
    <article class="{{post_class}}">
        <h2 class="hia-post-title"><a href="{{url}}">{{title}}</a></h2>
        <p class="hia-post-excerpt">{{excerpt}}</p>
    </article>
    {{/foreach}}
</section>

/* HIA Theme Builder 生成 — {{meta:name}}（Ghost 主题）
   Generated by HIA Theme Builder — target: Ghost publication theme.
   前置：Ghost 5.x；放入 content/themes/hia-theme/ 并在 Admin → Design 中激活。 */

:root {
    --hia-primary: {{token:primary.500}};
    --hia-primary-deep: {{token:primary.900}};
    --hia-primary-soft: {{token:primary.50}};
    --hia-primary-faint: {{token:primary.100}};
    --hia-secondary: {{token:secondary.500}};
    --hia-on-primary: {{token:on:primary}};
    --hia-text: {{token:primary.900}};
    --hia-text-soft: {{token:primary.700}};
    --hia-font-body: {{token:font:body}};
}

body { font-family: var(--hia-font-body); color: var(--hia-text); background: #ffffff; margin: 0; }
.hia-masthead { background: var(--hia-primary-deep); padding: 16px 24px; }
.hia-brand { color: var(--hia-on-primary); font-weight: 700; text-decoration: none; font-size: 20px; }
.hia-site-nav a { color: var(--hia-primary-faint); margin-left: 16px; text-decoration: none; }
.hia-main { max-width: 720px; margin: 0 auto; padding: 32px 24px; }
.hia-hero { background: var(--hia-primary-deep); color: var(--hia-on-primary); padding: 48px 24px; }
.hia-hero .hia-hero-sub { color: var(--hia-primary-faint); }
.hia-hero-action { background: var(--hia-primary); color: var(--hia-on-primary); padding: 8px 16px; border-radius: 6px; }
.hia-card { background: var(--hia-primary-soft); border-radius: 8px; padding: 16px 20px; }
.hia-card .hia-card-title { color: var(--hia-primary-deep); }
.hia-card .hia-card-text { color: var(--hia-text-soft); }
.hia-post-title a { color: var(--hia-primary); text-decoration: none; }
.hia-post-excerpt { color: var(--hia-text-soft); }
.hia-footer { color: var(--hia-text-soft); text-align: center; padding: 24px; border-top: 1px solid var(--hia-primary-soft); }
